def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    can_fit = (remaining >= 0)
    priority_scores = np.zeros_like(bins, dtype=float)

    if np.any(can_fit):
        fit_remaining = remaining[can_fit]
        avg_remaining = np.mean(fit_remaining)
        if avg_remaining != 0:
            normalized = 1.0 - np.abs(fit_remaining - avg_remaining) / (np.max(fit_remaining) - np.min(fit_remaining) + 1e-12)
        else:
            normalized = 1.0 - np.abs(fit_remaining) / (np.max(fit_remaining) - np.min(fit_remaining) + 1e-12)
        priority_scores[can_fit] = np.clip(normalized, 0, 1)

    return priority_scores
